// Demo: Hot/Warm/Cold Tiering — tier assignment by age and access heat
function tier(ageDays,hits){if(hits>10&&ageDays<30)return 'hot';if(ageDays<90)return 'warm';if(ageDays<365)return 'cold';return 'archive';}
var objs=[];for(var i=0;i<1;i++){var age=(i*37+1)%800;var hits=(i*13)%20;objs.push(tier(age,hits));}
var counts={};objs.forEach(function(t){counts[t]=(counts[t]||0)+1;});
console.log('technique: Hot/Warm/Cold Tiering');console.log('objects: '+objs.length);
console.log('tier mix: '+JSON.stringify(counts));

