// Demo: Hierarchical Storage Management — migration cost vs savings
var gb=28;var hotCost=0.023,warmCost=0.0125,coldCost=0.004;
var before=gb*hotCost;var after=gb*0.2*hotCost+gb*0.3*warmCost+gb*0.5*coldCost;
console.log('technique: Hierarchical Storage Management');console.log('data: '+gb+' GB');
console.log('all-hot monthly cost: $'+before.toFixed(2));
console.log('tiered monthly cost:  $'+after.toFixed(2));
console.log('savings: $'+(before-after).toFixed(2)+' ('+(100*(before-after)/before).toFixed(0)+'%)');

